*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.fn_GetPar, scwin.fn_SetPar = "";
scwin.gDepCd;
scwin.vScrenID = "ULDSTF24701.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  Set Code
 */
scwin.fn_init = function() {
    var strCbd = "",
        i, j;

    //기초지수
    var urlBas = "/listingCommon.do";
    urlBas += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    urlBas += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT_COMBO" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.basIdxCd.list";
    dst_BAS_IDX_CD.DataID = encodeURI(urlBas);
    dst_BAS_IDX_CD.reset();
    strCbd = "^전체";
    cmb_BAS_IDX_CD.CBData = strCbd;
    var arrCid = [{
        cid: "VALU_PRC_CALC_INST_CD",
        cnm: "cmb_VALU_PRC_CALC_INST_CD"
    }, {
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
        cnm: "cmb_EARNG_STRUCT_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='IDX_CALC_INST_CD','VALU_PRC_CALC_INST_CD','LOSS_LMT_ETN_EARNG_STRUCT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LOSS_LMT_ETN_LSTVALUMETDTHEOSRCH_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.losslmtetn.lstsrch.valu_methd_theo.list" + "&{P}param01=" + $c.stf.getObjectValue(cmb_VALU_PRC_CALC_INST_CD) + "&{P}param02=" + $c.stf.getObjectValue(cmb_VALU_PRC_CALC_INST_CD) + "&{P}param03=" + $c.stf.getObjectValue(cmb_EARNG_STRUCT_TP_CD) + "&{P}param04=" + $c.stf.getObjectValue(cmb_EARNG_STRUCT_TP_CD) + "&{P}param05=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + "&{P}param06=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + "&{P}param07=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(1, 6) + //기초지수idx_mkt_clss_id (6)||idx_seq(3) ||idx_lvrg_invrs_tp_cd (2) = 12
        "&{P}param08=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(1, 6) + "&{P}param09=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(7, 3) + "&{P}param10=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(7, 3) + "&{P}param11=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(10, 2) + "&{P}param12=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(10, 2) + "&{P}param13=" + $c.stf.getObjectValue(cmb_VALU_PRC_CALC_INST_CD) + "&{P}param14=" + $c.stf.getObjectValue(cmb_VALU_PRC_CALC_INST_CD) + "&{P}param15=" + $c.stf.getObjectValue(cmb_EARNG_STRUCT_TP_CD) + "&{P}param16=" + $c.stf.getObjectValue(cmb_EARNG_STRUCT_TP_CD) + "&{P}param17=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + "&{P}param18=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + "&{P}param19=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(1, 6) + //기초지수idx_mkt_clss_id (6)||idx_seq(3) ||idx_lvrg_invrs_tp_cd (2) = 12
        "&{P}param20=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(1, 6) + "&{P}param21=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(7, 3) + "&{P}param22=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(7, 3) + "&{P}param23=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(10, 2) + "&{P}param24=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD).substr(10, 2);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List); // 그리드명을 표기		

};
scwin.fn_OnStepComboSelChange = function(pValue, dst, targetObj, targetPValueNm) {
    var strCbd = "^전체";
    targetObj.CBData = strCbd;
    if (!(pValue == "" || pValue == null)) {
        for (j = 1; j <= dst.getTotalRow(); j++) {
            //alert(dst.NameValue(j, "TEXT")) ;
            if (dst.getCellData(j, targetPValueNm) == pValue) {
                strCbd += (strCbd == "" ? "" : ",") + dst.getCellData(j, "VALUE") + "^" + dst.getCellData(j, "TEXT");
            }
        }
        targetObj.CBData = strCbd;
        targetObj.ResetData();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리		

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (dts_List.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List, "손실제한 ETN 평가 방법론 현황", "", 1); //show false인것은 안보여준다.(type = 1)

    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_init();
};
scwin.cmb_IDX_CALC_INST_CD_OnSelChange = function() {
    scwin.fn_OnStepComboSelChange($c.stf.getObjectValue(cmb_IDX_CALC_INST_CD), dst_BAS_IDX_CD, cmb_BAS_IDX_CD, "PVALUE");
};
scwin.cmb_VALU_PRC_CALC_INST_CD_OnSelChange = function() {

};
